public abstract class GenericDAO<T> {

    protected static final EntityManagerFactory emf = Persistence.createEntityManagerFactory("DAW_PracticaPU");
    protected EntityManager em;
    private Class<T> entityClass;

    public GenericDAO(Class<T> entityClass) {
        this.entityClass = entityClass;
        this.em = emf.createEntityManager();
    }

    // Método auxiliar para obtener la transacción del servidor
    private UserTransaction getUserTransaction() {
        try {
            return (UserTransaction) new InitialContext().lookup("java:comp/UserTransaction");
        } catch (NamingException e) {
            throw new RuntimeException("Error al obtener UserTransaction JNDI", e);
        }
    }

    public void create(T entity) {
        UserTransaction utx = getUserTransaction();
        try {
            utx.begin(); // Empieza la transacción JTA
            em.joinTransaction(); // Une el EntityManager a esa transacción
            em.persist(entity);
            utx.commit(); // Confirma
        } catch (Exception e) {
            try {
                if (utx != null) utx.rollback();
            } catch (Exception re) {
                // Log rollback error
            }
            throw new RuntimeException(e);
        }
    }

    // ... Lo mismo para edit y remove ...
    public void edit(T entity) {
        UserTransaction utx = getUserTransaction();
        try {
            utx.begin();
            em.joinTransaction();
            em.merge(entity);
            utx.commit();
        } catch (Exception e) {
            try {
                if (utx != null) utx.rollback();
            } catch (Exception re) {}
            throw new RuntimeException(e);
        }
    }

    public void remove(T entity) {
        UserTransaction utx = getUserTransaction();
        try {
            utx.begin();
            em.joinTransaction();
            em.remove(em.merge(entity));
            utx.commit();
        } catch (Exception e) {
            try {
                if (utx != null) utx.rollback();
            } catch (Exception re) {}
            throw new RuntimeException(e);
